const ANON_KEY = 'REMPLACER_PAR_CLE_ANON_SUPABASE';

const checkList = [
  { name: 'Netlify Frontend',     url: 'https://assists.agenceattractor.com',                                    method: 'GET',  expectStatus: 200 },
  { name: 'Supabase Auth',        url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/auth/v1/health',               method: 'GET',  expectStatus: 200, headers: { apikey: ANON_KEY } },
  { name: 'Edge: chat-assistant', url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/functions/v1/chat-assistant',  method: 'POST', badStatus: 500 },
  { name: 'Edge: init-payment',   url: 'https://lgdgbrivnhgeupqhkckd.supabase.co/functions/v1/init-payment',    method: 'POST', badStatus: 500 },
];

const results = [];
for (const check of checkList) {
  try {
    const res = await this.helpers.httpRequest({
      method: check.method,
      url: check.url,
      headers: { 'Content-Type': 'application/json', ...(check.headers || {}) },
      body: check.method === 'POST' ? '{}' : undefined,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    const status = res.statusCode;
    const ok = check.expectStatus ? status === check.expectStatus : status !== check.badStatus;
    results.push({ name: check.name, status, ok });
  } catch(e) {
    results.push({ name: check.name, status: 0, ok: false, error: e.message });
  }
}

const failures = results.filter(r => !r.ok);
const now = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });
const rows = failures.map(f => `<tr><td style="padding:8px;border:1px solid #ddd"><b>${f.name}</b></td><td style="padding:8px;border:1px solid #ddd">HTTP ${f.status}</td><td style="padding:8px;border:1px solid #ddd">${f.error || 'Statut inattendu'}</td></tr>`).join('');
const emailHtml = `<h2 style="color:#cc0000">Assists — ${failures.length} panne(s) — ${now}</h2><table style="border-collapse:collapse;width:100%">${rows}</table><p><b>Verifier :</b> Supabase / Netlify / Resend</p>`;
const emailPayloadStr = JSON.stringify({ from: 'noreply@agenceattractor.com', to: 'macarthur.nguessankouassi@gmail.com', subject: 'ALERTE Assists — ' + failures.length + ' panne(s) — ' + now, html: emailHtml });

return [{ json: { results, failures, hasFailures: failures.length > 0, checkedAt: now, emailPayloadStr } }];
